extern "C" void seedless_wifi_default_calibration(uint8_t* firmware)
{
    firmware[0x1D] = 0x20;
    firmware[0x2C] = 0x38; firmware[0x2D] = 0x01;
    firmware[0x40] = 3; firmware[0x41] = 0x94;
    firmware[0x42] = 0x29; firmware[0x43] = 2;
    static const uint16_t values[16] = {2, 0x17, 0x26, 0x1818, 0x48, 0x4840, 0x58, 0x42,
        0x146, 0x8064, 0xE6E6, 0x2443, 0xE, 1, 1, 0x402};
    std::memcpy(firmware + 0x44, values, sizeof(values));
    std::memcpy(firmware + 0x64, BBINIT, sizeof(BBINIT));
    std::memcpy(firmware + 0xCE, RFINIT, sizeof(RFINIT));
    firmware[0xF7] = 2;
    std::memcpy(firmware + 0xF8, CHANDATA, sizeof(CHANDATA));
    std::memset(firmware + 0x134, 0xFF, 0x2E);
}
